import csv
import io
import re
from typing import List, Dict, Union


def _tolerant_rows(text: str) -> List[List[str]]:
    rows: List[List[str]] = []
    row: List[str] = []
    field: List[str] = []
    quoted = False
    after_quote = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if quoted:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                quoted = False
                after_quote = True
                i += 1
                continue
            field.append(ch)
            i += 1
            continue

        if ch == '"' and not field and not after_quote:
            quoted = True
            i += 1
            continue

        if ch == ",":
            row.append("".join(field))
            field = []
            after_quote = False
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            field = []
            rows.append(row)
            row = []
            after_quote = False
            if ch == "\r" and i + 1 < n and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        after_quote = False
        i += 1

    if field or row or after_quote or quoted:
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_rows(raw_csv: str) -> List[List[str]]:
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(100_000_000)
        try:
            return [
                list(row)
                for row in csv.reader(
                    io.StringIO(raw_csv, newline=""),
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    skipinitialspace=False,
                    strict=False,
                )
            ]
        except (csv.Error, UnicodeError):
            return _tolerant_rows(raw_csv)
    finally:
        csv.field_size_limit(old_limit)


def _header_likeness(row: List[str]) -> float:
    if not row:
        return 0.0

    score = 0.0
    for value in row:
        value = value.strip()
        if not value:
            continue
        if re.search(r"://|www\.", value, re.I):
            continue
        if re.fullmatch(r"[$€£¥]?\s*[-+]?\d+(?:[.,]\d+)*%?", value):
            continue
        if re.fullmatch(r"\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}", value):
            continue
        if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?", value):
            continue
        if re.search(r"[A-Za-z]", value):
            if len(value) <= 80:
                score += 1.0
            else:
                score += 0.25

    uniqueness = len(set(row)) / float(len(row))
    return (score / float(len(row))) + uniqueness * 0.1


def _find_header(rows: List[List[str]], width: int) -> int:
    candidates = [i for i, row in enumerate(rows) if len(row) == width]
    if not candidates:
        return 0

    best_index = candidates[0]
    best_score = float("-inf")

    for index in candidates:
        likeness = _header_likeness(rows[index])
        next_likeness = 0.0
        next_same_width = 0

        for j in range(index + 1, min(len(rows), index + 7)):
            if len(rows[j]) == width:
                next_same_width += 1
                if j == index + 1:
                    next_likeness = _header_likeness(rows[j])

        transition = max(0.0, likeness - next_likeness)
        score = likeness * 20.0 + transition * 12.0 + next_same_width - index * 0.001

        if score > best_score:
            best_score = score
            best_index = index

    return best_index


def _normalize_row(row: List[str], width: int, columns: List[str]) -> List[str]:
    values = list(row)

    if len(values) < width:
        return values + [""] * (width - len(values))

    if len(values) == width:
        return values

    url_index = -1
    for i, column in enumerate(columns):
        if re.search(r"\b(url|uri|link|website|web\s*address)\b", column, re.I):
            url_index = i
            break

    if 0 < url_index < width:
        source_url_index = -1
        for i, value in enumerate(values):
            if re.match(r"^\s*(?:https?|ftp)://", value, re.I):
                source_url_index = i
                if i >= url_index:
                    break

        if source_url_index > url_index:
            merge_start = url_index - 1
            values = (
                values[:merge_start]
                + [",".join(values[merge_start:source_url_index])]
                + values[source_url_index:]
            )

    if len(values) > width:
        values = values[: width - 1] + [",".join(values[width - 1:])]

    if len(values) < width:
        values += [""] * (width - len(values))

    return values


def parse_csv(raw_csv: str) -> Union[str, Dict[str, List]]:
    if not isinstance(raw_csv, str) or raw_csv == "":
        return {"columns": [], "rows": []}

    rows = _read_rows(raw_csv)
    if not rows:
        return {"columns": [], "rows": []}

    if rows[0]:
        rows[0][0] = rows[0][0].lstrip("\ufeff")

    expected_width = 9
    header_index = _find_header(rows, expected_width)
    columns = list(rows[header_index])

    if len(columns) < expected_width:
        columns += [""] * (expected_width - len(columns))
    elif len(columns) > expected_width:
        columns = columns[: expected_width - 1] + [
            ",".join(columns[expected_width - 1:])
        ]

    data_rows = [
        _normalize_row(row, expected_width, columns)
        for row in rows[header_index + 1:]
    ]

    return {"columns": columns, "rows": data_rows}
